import {
  Autocomplete,
  AutocompleteItem,
  Button,
  Select,
  SelectItem,
} from "@nextui-org/react";
import PropTypes from "prop-types";
import { GiCancel } from "react-icons/gi";
import { Post } from "@/utils/apiMethods";
import { BiPlusCircle } from "react-icons/bi";
import { useEffect, useMemo, useState, useCallback } from "react";

const useDebounce = (value, delay) => {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return [debouncedValue];
};

const SelectOption = (props) => {
  const {
    className = {},
    value = "",
    options = [],
    optionValue = "value",
    optionLabel = "label",
    onChange,
    isCustomOptionLabel = false,
    customLabelFunc = () => {},
    type = "select",
    isSearchable = false,
    isAddable = false,
    addURL = "",
    needSort = true,
    selectionMode = "single",
    onRemove = () => {},
    ...rest
  } = props;

  const [keyword, setKeyword] = useState("");
  const [debouncedKeyword] = useDebounce(keyword, 300);
  const [currentKey, setCurrentKey] = useState("");

  const getOptionLabel = useCallback(
    (option) => {
      if (typeof option === "string") return option;
      return isCustomOptionLabel
        ? customLabelFunc(option)
        : option[optionLabel] || "";
    },
    [optionLabel, isCustomOptionLabel, customLabelFunc],
  );

  const getOptionKey = useCallback(
    (option) => {
      if (typeof option === "string") return option;
      return option[optionValue] || option._id || option.id || option.value;
    },
    [optionValue],
  );

  const sortedOptions = useMemo(() => {
    if (!options || options.length === 0) return [];

    if (needSort)
      return [...options].sort((a, b) => {
        const nameA = getOptionLabel(a);
        const nameB = getOptionLabel(b);
        return nameA.localeCompare(nameB, undefined, { sensitivity: "base" });
      });

    return [...options];
  }, [options, needSort, getOptionLabel]);

  const searchRegex = useMemo(() => {
    if (!debouncedKeyword.trim()) return null;
    try {
      return new RegExp(debouncedKeyword.trim().split("").join(".*"), "i");
    } catch {
      return new RegExp(
        debouncedKeyword.trim().replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
        "i",
      );
    }
  }, [debouncedKeyword]);

  const filteredOptions = useMemo(() => {
    if (!isSearchable || !searchRegex) return sortedOptions;

    return sortedOptions.filter((option) => {
      const label = getOptionLabel(option);
      return searchRegex.test(label);
    });
  }, [sortedOptions, searchRegex, isSearchable, getOptionLabel]);

  const showCreateOption = useMemo(() => {
    return (
      type === "autocomplete" &&
      isAddable &&
      filteredOptions.length === 0 &&
      keyword.trim() &&
      addURL
    );
  }, [type, isAddable, filteredOptions.length, keyword, addURL]);

  const renderOptions = useMemo(() => {
    const baseOptions = filteredOptions.map((option) => ({
      key: getOptionKey(option),
      label: getOptionLabel(option),
      option: option,
      isCreateOption: false,
    }));

    if (showCreateOption) {
      baseOptions.push({
        key: "create-new",
        label: `Create New: ${keyword.trim()}`,
        option: keyword.trim(),
        isCreateOption: true,
      });
    }

    return baseOptions;
  }, [
    filteredOptions,
    showCreateOption,
    keyword,
    getOptionKey,
    getOptionLabel,
  ]);

  const handleChange = useCallback(
    (e) => {
      onChange({ name: e.target.name, value: e.target.value });
    },
    [onChange],
  );

  const handleCreate = useCallback(async () => {
    if (!addURL || !keyword.trim()) return false;

    try {
      const response = await Post(
        addURL,
        {
          name: keyword.trim(),
        },
        {},
        "value",
      );
      return response;
    } catch (error) {
      console.error("Error creating at ", addURL, error);
      return { isSuccess: false };
    }
  }, [addURL, keyword]);

  const handleMultiChange = useCallback(
    async (response, key) => {
      if (key === "create-new") {
        const res = await handleCreate();
        if (res.isSuccess) {
          response.value = res.data._id;
          response.needRefresh = true;
        }
      }

      setKeyword("");
      onChange(response);
    },
    [handleCreate, onChange],
  );

  const handleSelectionChange = useCallback(
    (key) => {
      if (type === "autocomplete") {
        if (selectionMode === "multiple") {
          if (key == "create-new") {
            const response = {
              name: rest.name,
              value: keyword,
            };
            handleMultiChange(response, key);
          } else {
            setCurrentKey(key);
          }
        } else {
          const response = {
            name: rest.name,
            value: key,
          };
          handleMultiChange(response, key);
        }
      }
    },
    [rest.name, selectionMode, type, keyword, handleMultiChange],
  );

  const handleInputChange = useCallback((input) => {
    setKeyword(input);
  }, []);

  const normalizedSelectedKeys = useMemo(() => {
    if (!value) selectionMode == "multiple" ? [] : "";
    if (Array.isArray(value)) return value;
    return [value];
  }, [value, selectionMode]);

  const commonClassNames = useMemo(
    () => ({
      trigger: "bg-white border-gray-300 hover:border-gray-400",
      popoverContent: "bg-white border border-gray-200 shadow-lg",
      listbox: "bg-white",
      base: "bg-white",
      ...(typeof className === "object" ? className : {}),
    }),
    [className],
  );

  const commonProps = useMemo(() => {
    const { name, ...otherProps } = rest;
    return {
      variant: "bordered",
      selectedKeys: normalizedSelectedKeys,
      name: name,
      selectionMode: selectionMode,
      ...otherProps,
    };
  }, [normalizedSelectedKeys, selectionMode, rest]);

  const handleAdd = () => {
    const response = {
      name: rest.name,
      value: currentKey,
    };
    handleMultiChange(response, currentKey);
  };

  const renderKey = (key) => {
    const idx = sortedOptions.findIndex(
      (option) => getOptionKey(option) == key,
    );
    if (idx != -1) return getOptionLabel(sortedOptions[idx]);
    return "Not Set";
  };

  if (type === "autocomplete") {
    return (
      <div className={`${isAddable && addURL ? "flex flex-col gap-3" : ""}`}>
        <div
          className={`${isAddable && addURL ? "flex gap-3 items-end justify-between" : ""}`}
        >
          <Autocomplete
            label="Search options"
            placeholder="Search or Choose options"
            allowsCustomValue={true}
            classNames={commonClassNames}
            onInputChange={handleInputChange}
            onSelectionChange={handleSelectionChange}
            items={renderOptions}
            {...commonProps}
          >
            {(item) => (
              <AutocompleteItem
                key={item.key}
                className="hover:bg-gray-50"
                textValue={item.label}
              >
                {item.isCreateOption ? (
                  <span>
                    Create New: <strong>{item.option}</strong>
                  </span>
                ) : (
                  item.label || "Not Set"
                )}
              </AutocompleteItem>
            )}
          </Autocomplete>

          {isAddable && addURL && (
            <Button
              className="flex gap-2 items-center justify-between py-6 font-semibold"
              disabled={!currentKey}
              onPress={() => currentKey && handleAdd()}
            >
              <BiPlusCircle /> Add
            </Button>
          )}
        </div>
        {selectionMode == "multiple" && normalizedSelectedKeys.length > 0 && (
          <div className="flex gap-3 items-center flex-wrap">
            {normalizedSelectedKeys.map((key, index) => (
              <div
                key={index + "-" + key}
                className="flex items-center gap-3 p-2 text-sm rounded-lg border-2"
              >
                <p>{renderKey(key)}</p>
                <span
                  className="hover:cursor-pointer"
                  onClick={() => onRemove(index)}
                >
                  <GiCancel />
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  }

  return (
    <Select
      classNames={commonClassNames}
      onChange={handleChange}
      items={renderOptions}
      {...commonProps}
    >
      {(item) => (
        <SelectItem
          key={item.key}
          className="hover:bg-gray-50"
          textValue={item.label}
        >
          {item.label || "Not Set"}
        </SelectItem>
      )}
    </Select>
  );
};

SelectOption.propTypes = {
  className: PropTypes.oneOfType([PropTypes.string, PropTypes.object]),
  value: PropTypes.any,
  options: PropTypes.array,
  optionValue: PropTypes.string,
  optionLabel: PropTypes.string,
  onChange: PropTypes.func.isRequired,
  isCustomOptionLabel: PropTypes.bool,
  customLabelFunc: PropTypes.func,
  type: PropTypes.oneOf(["select", "autocomplete"]),
  isSearchable: PropTypes.bool,
  isAddable: PropTypes.bool,
  addURL: PropTypes.string,
  needSort: PropTypes.bool,
  selectionMode: PropTypes.oneOf(["single", "multiple"]),
  onRemove: PropTypes.func,
};

export default SelectOption;
