import Swal from "sweetalert2";
import toast from "react-hot-toast";
import { customAxios } from "./axiosInstance";
import { errorResponse, successResponse } from "@/helpers/response";

export const Get = async (url, params = {}, api = customAxios()) => {
  try {
    const response = await api.get(url, { params });
    return response.data;
  } catch (error) {
    if (error.status == "404")
      return {
        isSuccess: true,
        data: [],
      };

    return {
      success: false,
      data: [],
      message: error?.response?.data?.message,
    };
  }
};

export const EmailWithPost = async (
  url,
  data,
  conf,
  text,
  api = customAxios(),
) => {
  await api
    .post(url, data, conf)
    .then(function (res) {
      Swal.fire({
        title: "Successful!",
        text: `Check your ${text} for password!`,
        icon: "success",

        showConfirmButton: false,
        timer: 4000,
      });

      return res.data.data;
    })
    .catch(function (err) {
      Swal.fire({
        title: "Something Wrong!",
        text: err.response.data.message,
        icon: "warning",
        showConfirmButton: false,
        timer: 2000,
      });
    });
};

export const Post = async (
  url,
  data,
  config = {},
  text,
  api = customAxios(),
) => {
  try {
    const res = await api.post(url, data, config);
    if (res.data.isSuccess) {
      if (url.split("?")[0] === "auth/login") {
        toast.success("Login successfully!");
      } else {
        toast.success(`The ${text} had been created successfully!`);
      }
    }
    return res.data;
  } catch (error) {
    toast.error(error.response.data.message);

    return errorResponse(error.response.data.message, []);
  }
};

export const PostWithFormData = async (
  url,
  data,
  config = {},
  text,
  api = customAxios(),
) => {
  return await Post(
    url,
    data,
    {
      headers: {
        "Content-Type": "multipart/form-data",
      },
      ...config,
    },
    text,
    api,
  );
};

export const Update = async (
  url,
  id,
  data,
  conf,
  text,
  api = customAxios(),
) => {
  try {
    const res = await api.put(url + id, data, conf);
    if (res.data.isSuccess) {
      toast.success("Saved Your Changes!");
    } else {
      toast.error("Something Wrong!");
    }

    return res.data;
  } catch (error) {
    toast.error(error.response.data.message);

    return errorResponse(error.response.data.message, []);
  }
};

