import PropTypes from "prop-types";
import { Upload, X } from "lucide-react";
import { useCallback, useState, useEffect, useRef } from "react";

const MultipleFileUpload = ({
  label = "Upload Images",
  value = [],
  id,
  onChange,
  accept = "image/*",
  isDisabled = false,
  maxFiles = 10,
  maxSizeMB = 5,
  ...rest
}) => {
  const [previews, setPreviews] = useState([]);
  const [error, setError] = useState("");
  const [isDragging, setIsDragging] = useState(false);
  const dragCounter = useRef(0);

  useEffect(() => {
    if (!value || value.length === 0) {
      setPreviews([]);
      return;
    }

    const newPreviews = [];
    const cleanupFunctions = [];

    value.forEach((file, index) => {
      if (file instanceof File) {
        const objectUrl = URL.createObjectURL(file);
        newPreviews.push({
          id: `${file.name}-${index}`,
          url: objectUrl,
          name: file.name,
          size: file.size,
          type: file.type,
        });
        cleanupFunctions.push(() => URL.revokeObjectURL(objectUrl));
      } else if (file?.url) {
        newPreviews.push({
          id: file._id || `existing-${index}`,
          url: file.url,
          name: file.originalname || file.name,
          size: file.size,
          type: file.mimetype || file.type,
        });
      }
    });

    setPreviews(newPreviews);

    return () => {
      cleanupFunctions.forEach((cleanup) => cleanup());
    };
  }, [value]);

  const validateFile = useCallback(
    (file) => {
      const fileSizeMB = file.size / (1024 * 1024);

      if (fileSizeMB > maxSizeMB) {
        setError(`File "${file.name}" is too large. Max size: ${maxSizeMB}MB`);
        return false;
      }

      if (accept && accept !== "*") {
        const acceptedTypes = accept.split(",").map((type) => type.trim());
        const fileType = file.type;
        const fileExtension = "." + file.name.split(".").pop();

        const isAccepted = acceptedTypes.some((acceptType) => {
          if (acceptType.endsWith("/*")) {
            return fileType.startsWith(acceptType.replace("/*", ""));
          }
          return acceptType === fileType || acceptType === fileExtension;
        });

        if (!isAccepted) {
          setError(`File "${file.name}" type not accepted`);
          return false;
        }
      }

      return true;
    },
    [accept, maxSizeMB],
  );

  const handleFilesChange = useCallback(
    (files) => {
      const currentFiles = Array.isArray(value) ? value : [];
      const filesArray = Array.from(files);

      if (currentFiles.length + filesArray.length > maxFiles) {
        setError(`Maximum ${maxFiles} files allowed`);
        return;
      }

      const validFiles = filesArray.filter((file) => validateFile(file));

      if (validFiles.length > 0) {
        setError("");
        const newFiles = [...currentFiles, ...validFiles];
        onChange({ name: id, value: newFiles });
      }
    },
    [value, id, onChange, maxFiles, validateFile],
  );

  const handleFileChange = useCallback(
    (e) => {
      if (e.target.files && e.target.files.length > 0) {
        handleFilesChange(e.target.files);
      }
    },
    [handleFilesChange],
  );

  const handleRemove = useCallback(
    (indexToRemove, e) => {
      e.stopPropagation();
      const currentFiles = Array.isArray(value) ? value : [];
      const newFiles = currentFiles.filter(
        (_, index) => index !== indexToRemove,
      );
      onChange({ name: id, value: newFiles });
      setError("");

      if (newFiles.length === 0) {
        const input = document.getElementById(id);
        if (input) input.value = "";
      }
    },
    [value, onChange, id],
  );

  const handleClearAll = useCallback(
    (e) => {
      e.stopPropagation();
      onChange({ name: id, value: [] });
      setError("");
      const input = document.getElementById(id);
      if (input) input.value = "";
    },
    [onChange, id],
  );

  const handleDragEnter = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounter.current++;
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      setIsDragging(true);
    }
  }, []);

  const handleDragLeave = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
    dragCounter.current--;
    if (dragCounter.current === 0) {
      setIsDragging(false);
    }
  }, []);

  const handleDragOver = useCallback((e) => {
    e.preventDefault();
    e.stopPropagation();
  }, []);

  const handleDrop = useCallback(
    (e) => {
      e.preventDefault();
      e.stopPropagation();

      setIsDragging(false);
      dragCounter.current = 0;

      if (isDisabled) return;

      if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        handleFilesChange(e.dataTransfer.files);
      }
    },
    [isDisabled, handleFilesChange],
  );

  const formatFileSize = (bytes) => {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return Math.round((bytes / Math.pow(k, i)) * 100) / 100 + " " + sizes[i];
  };

  const currentFileCount = Array.isArray(value) ? value.length : 0;
  const remainingSlots = maxFiles - currentFileCount;

  return (
    <div className="space-y-3">
      <div
        onDragEnter={handleDragEnter}
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className={`
          relative border-2 border-dashed rounded-xl 
          transition-all duration-300 ease-in-out
          ${
            isDisabled || remainingSlots === 0
              ? "opacity-50 cursor-not-allowed bg-default-50"
              : "cursor-pointer hover:border-primary-400"
          }
          ${
            isDragging && !isDisabled && remainingSlots > 0
              ? "border-primary-500 bg-primary-50 scale-[1.02] shadow-lg"
              : error
                ? "border-danger bg-danger-50/30"
                : currentFileCount > 0
                  ? "border-success-300 bg-success-50/30"
                  : "border-default-300 bg-white"
          }
        `}
      >
        <label
          htmlFor={id}
          className={`
            relative block w-full p-6
            ${isDisabled || remainingSlots === 0 ? "cursor-not-allowed" : "cursor-pointer"}
          `}
        >
          {isDragging && !isDisabled && remainingSlots > 0 && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-primary-500/10 rounded-xl z-10 pointer-events-none">
              <Upload className="w-12 h-12 text-primary-500 animate-bounce" />
              <p className="text-primary-600 font-semibold mt-3">
                Drop your files here
              </p>
            </div>
          )}

          <div className="flex flex-col items-center justify-center gap-3 py-4">
            <div className="p-4 rounded-full bg-default-100">
              <Upload className="w-8 h-8 text-default-500" />
            </div>

            <div className="text-center space-y-1">
              <p className="text-base font-semibold text-default-700">
                {label}
              </p>
              <p className="text-sm text-default-500">
                Drag and drop or{" "}
                <span className="text-primary-500 font-medium">browse</span>
              </p>
              <p className="text-xs text-default-400">
                {accept === "image/*"
                  ? `PNG, JPG, GIF, WEBP up to ${maxSizeMB}MB each`
                  : `Max ${maxSizeMB}MB per file`}
              </p>
              <p className="text-xs font-medium text-default-600 mt-2">
                {currentFileCount} / {maxFiles} files selected
              </p>
            </div>
          </div>

          <input
            id={id}
            name={id}
            type="file"
            onChange={handleFileChange}
            className="hidden"
            accept={accept}
            disabled={isDisabled || remainingSlots === 0}
            multiple
            aria-describedby={error ? `${id}-error` : undefined}
            {...rest}
          />
        </label>
      </div>

      {error && (
        <div className="flex items-start gap-2 p-3 rounded-lg bg-danger-50 border border-danger-200">
          <svg
            className="w-5 h-5 text-danger-500 flex-shrink-0 mt-0.5"
            fill="currentColor"
            viewBox="0 0 20 20"
          >
            <path
              fillRule="evenodd"
              d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
              clipRule="evenodd"
            />
          </svg>
          <p id={`${id}-error`} className="text-sm text-danger-700 font-medium">
            {error}
          </p>
        </div>
      )}

      {previews.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-semibold text-default-700">
              Selected Files ({previews.length})
            </h4>
            <button
              type="button"
              onClick={handleClearAll}
              disabled={isDisabled}
              className="text-xs text-danger-500 hover:text-danger-600 font-medium transition-colors disabled:opacity-50"
            >
              Clear All
            </button>
          </div>

          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {previews.map((preview, index) => (
              <div
                key={preview.id}
                className="relative group rounded-xl overflow-hidden border-2 border-default-200 bg-white hover:border-primary-300 transition-all"
              >
                <div className="aspect-square relative">
                  <img
                    src={preview.url}
                    alt={preview.name}
                    className="w-full h-full object-cover"
                    loading="lazy"
                  />

                  <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <div className="absolute bottom-0 left-0 right-0 p-2">
                      <p className="text-white text-xs font-medium truncate">
                        {preview.name}
                      </p>
                      <p className="text-white/80 text-xs">
                        {formatFileSize(preview.size)}
                      </p>
                    </div>

                    <button
                      type="button"
                      onClick={(e) => handleRemove(index, e)}
                      disabled={isDisabled}
                      className="
                        absolute top-2 right-2 p-1.5 rounded-full 
                        bg-danger-500 text-white shadow-xl
                        hover:bg-danger-600 hover:scale-110
                        transform transition-all duration-200
                        disabled:opacity-50 disabled:cursor-not-allowed
                      "
                      aria-label={`Remove ${preview.name}`}
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

MultipleFileUpload.propTypes = {
  label: PropTypes.string,
  value: PropTypes.array,
  id: PropTypes.string.isRequired,
  onChange: PropTypes.func.isRequired,
  accept: PropTypes.string,
  isDisabled: PropTypes.bool,
  maxFiles: PropTypes.number,
  maxSizeMB: PropTypes.number,
};

export default MultipleFileUpload;
