import axios from "axios";

const url = import.meta.env.VITE_API_BASE_URL;

export const api = axios.create({
  baseURL: url,
  headers: {
    "Content-Type": "application/json",
  },
});

export const apiInterception = (api) => {
  api.interceptors.request.use(
    (config) => {
      const token = localStorage.getItem("@account_token");
      const localUser = localStorage.getItem("@account_authenticatedUser");

      let user = {};
      try {
        user = localUser ? JSON.parse(localUser) : {};
      } catch (error) {
        console.error("Error parsing user data:", error);
      }

      if (token) {
        config.headers.Authorization = `Bearer ${token}`;

        const relatedBranch = user.relatedBranch?._id || user.relatedBranch;

        if (relatedBranch) {
          config.params = {
            ...config.params,
            relatedBranch: relatedBranch,
          };

          if (["post", "put", "patch"].includes(config.method)) {
            if (config.data instanceof FormData) {
              if (!config.data.has("relatedBranch"))
                config.data.append("relatedBranch", relatedBranch);
              else if (!config.data.get("relatedBranch"))
                config.data.set("relatedBranch", relatedBranch);

              if (
                !config.data.has("createdBy") ||
                !config.data.get("createdBy")
              )
                config.data.append("createdBy", user._id || user.id);
              else if (!config.data.get("createdBy"))
                config.data.set("createdBy", user._id || user.id);
            } else {
              config.data = {
                ...config.data,
                createdBy: user._id || user.id,
                relatedBranch,
              };
            }
          }
        }
      }

      return config;
    },
    (error) => {
      return Promise.reject(error);
    },
  );

  return api;
};

export const customAxios = (
  dynamicBaseURL = import.meta.env.VITE_API_BASE_URL,
) => {
  const axiosInstance = axios.create({
    baseURL: dynamicBaseURL,
    headers: {
      "Content-Type": "application/json",
    },
  });

  return apiInterception(axiosInstance);
};

export const apiInstance = customAxios();
export const ImageURL = import.meta.env.VITE_API_BASE_URL + "uploads/";
